function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let index=0;index<text.length;index+=1){const char=text[index],next=text[index+1];if(char==='"'&&quoted&&next==='"'){cell+='"';index+=1;}else if(char==='"'){quoted=!quoted;}else if(char===','&&!quoted){row.push(cell);cell='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')index+=1;row.push(cell);if(row.some((value)=>value!==''))rows.push(row);row=[];cell='';}else cell+=char;}if(cell||row.length){row.push(cell);rows.push(row);}const headers=rows.shift().map((header)=>header.replace(/^\uFEFF/,''));return rows.map((values)=>Object.fromEntries(headers.map((header,index)=>[header,values[index]||''])));}
function categoryFor(row){const titleTags=`${row.TITLE} ${row.TAGS}`.toLowerCase();if(titleTags.includes('clearance'))return'clearance-section';if(/completed.*(pen|keychain)|finished.*(pen|keychain)/.test(titleTags))return'completed-pens-keychains';if(/cup accessories, cup charm,/.test(titleTags))return'cup-charms';if((titleTags.includes('charm')||titleTags.includes('dangle'))&&!titleTags.includes('cup charm'))return'charms-dangles';if(titleTags.includes('focal'))return'focal-beads';if(titleTags.includes('flatback'))return'acrylic-flatbacks';if(titleTags.includes('rhinestone'))return'rhinestone-beads';if((titleTags.includes('spacer')||titleTags.includes('accessor'))&&!titleTags.includes('cup charm')&&!titleTags.includes('cup accessor'))return'spacers-accessories';if(titleTags.includes('mix')||titleTags.includes('bundle')||titleTags.includes('kit'))return'mixes-bundles-kits';if(/beadable.*pen.*blank|beaded.*pen.*blank|pen.*blank/.test(titleTags))return'beadable-pen-blanks';if(/10\s*(\/|or)\s*12\s*mm|10mm|12mm/.test(titleTags)&&titleTags.includes('acrylic'))return'10-12mm-acrylic-beads';if(/16\s*mm/.test(titleTags)&&titleTags.includes('acrylic'))return'16mm-acrylic-beads';if(/20\s*mm/.test(titleTags)&&titleTags.includes('acrylic'))return'20mm-acrylic-beads';if(titleTags.includes('silicone'))return(/print|paw|letter|face|pattern|design|swirl/.test(titleTags)?'silicone-printed-style':'silicone-solid-color');return'uncategorized';}
async function ensureSupabaseClient(){if(window.beadSupabase)return window.beadSupabase;if(window.beadSupabaseReady)return window.beadSupabaseReady;const loadScript=(source)=>new Promise((resolve)=>{const script=document.createElement('script');script.src=source;script.onload=resolve;script.onerror=()=>resolve();document.head.append(script);});window.beadSupabaseReady=(window.supabase?Promise.resolve():loadScript('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.57.4/dist/umd/supabase.min.js')).then(()=>window.beadSupabase?window.beadSupabase:loadScript('supabase-client.js').then(()=>window.beadSupabase));return window.beadSupabaseReady;}
