async function loadCatalog(){const localCatalog=await loadLocalCatalog();const client=await ensureSupabaseClient();if(client){let productQuery=client.from('products').select('id,external_id,sku,category_slug,subcategory_slug,name,seo_title,search_text,description,item_details,shipping_details,etsy_units_per_sale,price,promo_price,promo_starts_at,promo_ends_at,promo_discount_percent,promo_skus,quantity,visible,waitlist_enabled,added_at,low_stock_threshold,badges');if(document.body.dataset.page!=='Admin'){productQuery=productQuery.eq('visible',true);}const {data,error}=await productQuery.order('added_at',{ascending:false});if(!error&&data?.length){const productIds=data.map((item)=>item.id);const [imageResult,optionResult]=await Promise.all([client.from('product_images').select('product_id,url,alt_text,sort_order,media_type').in('product_id',productIds).order('sort_order'),client.from('product_options').select('id,product_id,name,required,sort_order,product_option_values(id,label,price_delta,sku,inventory_sku,inventory_units,quantity,low_stock_threshold,image_url,unit_type,sort_order)').in('product_id',productIds).order('sort_order')]);const imagesByProduct=new Map();(imageResult.data||[]).forEach((image)=>{const images=imagesByProduct.get(image.product_id)||[];images.push(image);imagesByProduct.set(image.product_id,images);});catalog=data.map((item)=>{const media=imagesByProduct.get(item.id)||[];const activePromo=item.promo_discount_percent>0&&(!item.promo_starts_at||Date.parse(item.promo_starts_at)<=Date.now())&&(!item.promo_ends_at||Date.parse(item.promo_ends_at)>=Date.now());return {...item,id:item.external_id||item.id,databaseId:item.id,externalId:item.external_id,seoTitle:item.seo_title||item.name,searchText:item.search_text||item.seo_title||item.name,category:item.subcategory_slug||item.category_slug,image:media.find((entry)=>entry.media_type!=='video')?.url||'product-mix.jpg',images:media.filter((entry)=>entry.media_type!=='video').map((entry)=>entry.url),media:media.map((entry)=>({url:entry.url,type:entry.media_type||'image'})),options:(optionResult.data||[]).filter((option)=>option.product_id===item.id).map((option)=>({name:option.name,required:option.required,values:(option.product_option_values||[]).sort((a,b)=>a.sort_order-b.sort_order).map((value)=>({label:value.label,price:Number(item.price||0)+Number(value.price_delta||0),sku:value.sku||'',inventorySku:value.inventory_sku||'',inventoryUnits:Number(value.inventory_units)||1,imageUrl:value.image_url||'',unitType:value.unit_type||'Each',quantity:value.quantity===null?null:Number(value.quantity)||0,lowStockThreshold:Number(value.low_stock_threshold)||0}))})),price:Number(item.price)||0,promoPrice:null,displayPrice:Number(item.price)||0,promoDiscountPercent:Number(item.promo_discount_percent)||0,promoSkus:Array.isArray(item.promo_skus)?item.promo_skus:[],addedAt:item.added_at,waitlist:item.waitlist_enabled,description:item.description||'',itemDetails:item.item_details||'',shippingDetails:item.shipping_details||'',etsyUnitsPerSale:Number(item.etsy_units_per_sale)||1,quantity:Number(item.quantity)||0,lowStockThreshold:Number(item.low_stock_threshold)||0,badges:Array.isArray(item.badges)?item.badges:[]};});return catalog;}if(!error){catalog=[];return catalog;}}catalog=localCatalog;return catalog;}
async function applyCanonicalInventory(){if(!window.beadSupabase||!catalog.length)return catalog;const skus=[...new Set(catalog.flatMap((item)=>[item.sku||'',...(item.options||[]).flatMap((option)=>option.values||[])]).map((value)=>typeof value==='object'?(value.inventorySku||value.sku):value).filter(Boolean))];if(!skus.length)return catalog;const result=await window.beadSupabase.from('storefront_inventory_skus').select('sku,quantity_on_hand,reserve_quantity,reorder_point,price,unit_type,weight_value,weight_unit').in('sku',skus);if(result.error)return catalog;const bySku=new Map((result.data||[]).map((record)=>[record.sku,record]));catalog.forEach((item)=>{item.options=(item.options||[]).map((option)=>({...option,values:(option.values||[]).map((value)=>{if(typeof value!=='object')return value;const record=bySku.get(value.inventorySku||value.sku);if(!record)return value;return {...value,sku:record.sku,inventorySku:record.sku,price:record.price===null?value.price:Number(record.price),unitType:record.unit_type||value.unitType||'Each',weight:record.weight_value===null||record.weight_value===undefined?null:Number(record.weight_value),weightUnit:record.weight_unit||value.weightUnit||'oz',reserveQuantity:Number(record.reserve_quantity)||0,quantity:Math.max(0,(Number(record.quantity_on_hand)||0)-(Number(record.reserve_quantity)||0)),lowStockThreshold:Number(record.reorder_point)||0};})}));const variants=(item.options||[]).flatMap((option)=>option.values||[]).filter((value)=>typeof value==='object'&&value.sku);const itemRecord=bySku.get(item.sku);if(itemRecord){item.weight=itemRecord.weight_value===null||itemRecord.weight_value===undefined?null:Number(itemRecord.weight_value);item.weightUnit=itemRecord.weight_unit||'oz';}if(variants.length)item.quantity=variants.reduce((total,value)=>total+Number(value.quantity||0),0);else if(itemRecord)item.quantity=Math.max(0,(Number(itemRecord.quantity_on_hand)||0)-(Number(itemRecord.reserve_quantity)||0));});return catalog;}
const loadStorefrontBundleComponents=async()=>{if(!window.beadSupabase||!catalog.length)return catalog;const result=await window.beadSupabase.from('inventory_bundle_components').select('bundle_sku,component_sku,quantity,sort_order').order('bundle_sku').order('sort_order');if(result.error)return catalog;const byBundle=new Map();(result.data||[]).forEach((entry)=>{const key=String(entry.bundle_sku||'').trim().toLowerCase();const rows=byBundle.get(key)||[];rows.push({componentSku:entry.component_sku,quantity:Math.max(1,Number(entry.quantity)||1),sortOrder:Number(entry.sort_order)||0});byBundle.set(key,rows);});catalog.forEach((item)=>{const skus=[item.sku||'',...(item.options||[]).flatMap((option)=>option.values||[]).map((value)=>typeof value==='object'?(value.inventorySku||value.sku):value)].filter(Boolean);item.bundleComponents=skus.flatMap((sku)=>byBundle.get(String(sku).trim().toLowerCase())||[]);});window.storefrontBundleRecipes=byBundle;return catalog;};
const storefrontSkuQuantity=(sku)=>{const needle=String(sku||'').trim().toLowerCase();if(!needle)return 0;for(const item of catalog){for(const option of item.options||[]){for(const value of option.values||[]){if(typeof value==='object'&&String(value.inventorySku||value.sku||'').trim().toLowerCase()===needle)return Math.max(0,Number(value.quantity)||0);}}if(String(item.sku||'').trim().toLowerCase()===needle)return Math.max(0,Number(item.quantity)||0);}return 0;};
const storefrontInventoryRequirements=(sku,units=1,path=[])=>{const needle=String(sku||'').trim();const amount=Math.max(1,Number(units)||1);if(!needle||path.map((value)=>value.toLowerCase()).includes(needle.toLowerCase()))return[];const recipes=window.storefrontBundleRecipes?.get(needle.toLowerCase())||[];if(!recipes.length)return[{sku:needle,quantity:amount}];return recipes.flatMap((recipe)=>storefrontInventoryRequirements(recipe.componentSku,amount*recipe.quantity,[...path,needle])).reduce((rows,entry)=>{const existing=rows.find((row)=>row.sku.toLowerCase()===entry.sku.toLowerCase());if(existing)existing.quantity+=entry.quantity;else rows.push({...entry});return rows;},[]);};
const storefrontAvailableQuantity=(sku,units=1)=>{const requirements=storefrontInventoryRequirements(sku,units);return requirements.length?Math.min(...requirements.map((entry)=>Math.floor(storefrontSkuQuantity(entry.sku)/entry.quantity))):0;};
