async function persistCloudCart(){const user=await cloudStoreUser();if(!user)return;const items=bagItems();await window.beadSupabase.from('customer_carts').upsert({user_id:user.id,updated_at:new Date().toISOString()},{onConflict:'user_id'});await window.beadSupabase.from('customer_cart_items').delete().eq('cart_user_id',user.id);if(items.length)await window.beadSupabase.from('customer_cart_items').insert(await Promise.all(items.map(async(item)=>({cart_user_id:user.id,product_id:await resolveProductId(item.id),line_key:storeCartLineKey(item),quantity:item.quantity,selected_options:item.selectedOptions||{},updated_at:new Date().toISOString()}))));}
