async function syncCloudStore(){const user=await cloudStoreUser();if(!user)return;const [cartResult,favoriteResult]=await Promise.all([window.beadSupabase.from('customer_cart_items').select('product_id,quantity,selected_options,products(external_id)').eq('cart_user_id',user.id),window.beadSupabase.from('customer_favorites').select('product_id,products(external_id)').eq('user_id',user.id)]);const localBag=bagItems();const cloudBag=(cartResult.data||[]).map((item)=>({id:item.products?.external_id||item.product_id,quantity:Number(item.quantity)||1,selectedOptions:item.selected_options||[]}));const mergedBag=[...cloudBag];localBag.forEach((localItem)=>{const existing=mergedBag.find((item)=>storeCartLineKey(item)===storeCartLineKey(localItem));if(existing)existing.quantity=Math.max(existing.quantity,Number(localItem.quantity)||1);else mergedBag.push(localItem);});writeStore(storeKeys.bag,mergedBag);const cloudFavorites=(favoriteResult.data||[]).map((item)=>item.products?.external_id||item.product_id);const mergedFavorites=[...new Set([...cloudFavorites,...wishlistItems()])];writeStore(storeKeys.wishlist,mergedFavorites);await persistCloudCart();for(const id of mergedFavorites.filter((favorite)=>!cloudFavorites.includes(favorite)))await persistCloudFavorite(id,true);updateBagCount();window.dispatchEvent(new Event('bead-store-synced'));}
