function updateBagCount(){const count=bagItems().reduce((total,item)=>total+item.quantity,0);document.querySelectorAll('#bag-count,.bag i').forEach((element)=>{element.textContent=count;});}
const shippingWeightToOz=(value,unit)=>{const amount=Number(value)||0;return unit==='lb'?amount*16:unit==='g'?amount/28.349523125:unit==='kg'?amount*35.27396195:amount;};
const shippingCartOption=(item,entry)=>{const options=Array.isArray(entry?.selectedOptions)?entry.selectedOptions:[];return options.find((option)=>option?.inventorySku||option?.sku)||options[0]||null;};
const shippingCartTotals=(items=bagItems())=>items.reduce((totals,entry)=>{const item=findProduct(entry.id);if(!item)return totals;const option=shippingCartOption(item,entry);const quantity=Math.max(0,Number(entry.quantity)||0);const price=Number(option?.price??item.price)||0;const weight=option?.weight===null||option?.weight===undefined?item.weight:option.weight;const weightUnit=option?.weightUnit||item.weightUnit||'oz';totals.subtotal+=price*quantity;totals.weightOz+=shippingWeightToOz(weight,weightUnit)*quantity;totals.units+=quantity;return totals;},{subtotal:0,weightOz:0,units:0});
const shippingBoxForWeight=(weightOz,config=window.productStoreConfig||{})=>{const boxes=(Array.isArray(config.shippingBoxes)?config.shippingBoxes:[]).map((box,index)=>({...box,index,maxWeightOz:Number(box.maxWeightOz),lengthIn:Number(box.lengthIn),widthIn:Number(box.widthIn),heightIn:Number(box.heightIn),fallbackRate:String(box.fallbackRate??'').trim()===''?5:Number(box.fallbackRate)})).filter((box)=>box.name&&Number.isFinite(box.maxWeightOz)&&box.maxWeightOz>=0).sort((a,b)=>a.maxWeightOz-b.maxWeightOz);return boxes.find((box)=>box.maxWeightOz>=weightOz)||boxes.at(-1)||null;};
const shippingFallbackQuote=(items=bagItems(),postalCode='')=>{const config=window.productStoreConfig||{};const totals=shippingCartTotals(items);const threshold=Math.max(0,Number(config.freeShippingThreshold??35));const box=shippingBoxForWeight(totals.weightOz,config);if(totals.subtotal>=threshold)return{...totals,amount:0,free:true,box,method:'Free shipping'};return{...totals,amount:box?box.fallbackRate:5,free:false,box,method:'Fixed test shipping',postalCode};};
const storeShipping={totals:shippingCartTotals,boxForWeight:shippingBoxForWeight,quoteFallback:shippingFallbackQuote,quote:async(items=bagItems(),postalCode='')=>{const config=window.productStoreConfig||{};const fallback=shippingFallbackQuote(items,postalCode);if(fallback.free||config.shippingCarrier!=='ups'||!window.beadSupabase?.functions?.invoke||!config.shippingOriginPostalCode||!postalCode||!fallback.box?.lengthIn||!fallback.box?.widthIn||!fallback.box?.heightIn)return fallback;try{const result=await window.beadSupabase.functions.invoke('shipping-rates',{body:{from:{postalCode:config.shippingOriginPostalCode,city:config.shippingOriginCity,state:config.shippingOriginState,countryCode:'US'},to:{postalCode,countryCode:'US'},package:{weightOz:fallback.weightOz,lengthIn:fallback.box.lengthIn,widthIn:fallback.box.widthIn,heightIn:fallback.box.heightIn}}});if(result.error||!result.data?.rates?.length)return fallback;const rate=result.data.rates[0];return{...fallback,amount:Number(rate.amount)||fallback.amount,method:rate.serviceName||'UPS shipping',rates:result.data.rates};}catch(error){return fallback;}}};
