const storefrontSkuWeight=(sku,path=[])=>{const needle=String(sku||'').trim();if(!needle||path.map((value)=>value.toLowerCase()).includes(needle.toLowerCase()))return 0;const recipes=window.storefrontBundleRecipes?.get(needle.toLowerCase())||[];if(recipes.length)return recipes.reduce((total,recipe)=>total+storefrontSkuWeight(recipe.componentSku,[...path,needle])*recipe.quantity,0);for(const item of catalog){for(const option of item.options||[]){for(const value of option.values||[]){if(typeof value==='object'&&String(value.inventorySku||value.sku||'').trim().toLowerCase()===needle.toLowerCase())return shippingWeightToOz(value.weight,value.weightUnit||'oz');}}if(String(item.sku||'').trim().toLowerCase()===needle.toLowerCase())return shippingWeightToOz(item.weight,item.weightUnit||'oz');}return 0;};
const originalStoreShippingTotals=storeShipping.totals;
const storefrontShippingTotals=(items=bagItems())=>{const totals=originalStoreShippingTotals(items);return{...totals,weightOz:items.reduce((weight,entry)=>{const item=findProduct(entry.id);if(!item)return weight;const option=shippingCartOption(item,entry);const quantity=Math.max(0,Number(entry.quantity)||0);const sku=option?.inventorySku||option?.sku;if(sku)return weight+storefrontSkuWeight(sku,[])*Math.max(1,Number(option?.inventoryUnits)||1)*quantity;const fallbackWeight=option?.weight===null||option?.weight===undefined?item.weight:option.weight;return weight+shippingWeightToOz(fallbackWeight,option?.weightUnit||item.weightUnit||'oz')*quantity;},0)};};
const bundleShippingFallback=(items=bagItems(),postalCode='')=>{const config=window.productStoreConfig||{};const totals=storefrontShippingTotals(items);const threshold=Math.max(0,Number(config.freeShippingThreshold??35));const box=shippingBoxForWeight(totals.weightOz,config);if(totals.subtotal>=threshold)return{...totals,amount:0,free:true,box,method:'Free shipping'};return{...totals,amount:box?box.fallbackRate:5,free:false,box,method:'Fixed test shipping',postalCode};};
