storeShipping.quote=async(items=bagItems(),postalCode='')=>{const config=window.productStoreConfig||{};const fallback=bundleShippingFallback(items,postalCode);if(fallback.free||config.shippingCarrier!=='ups'||!window.beadSupabase?.functions?.invoke||!config.shippingOriginPostalCode||!postalCode||!fallback.box?.lengthIn||!fallback.box?.widthIn||!fallback.box?.heightIn)return fallback;try{const result=await window.beadSupabase.functions.invoke('shipping-rates',{body:{from:{postalCode:config.shippingOriginPostalCode,city:config.shippingOriginCity,state:config.shippingOriginState,countryCode:'US'},to:{postalCode,countryCode:'US'},package:{weightOz:fallback.weightOz,lengthIn:fallback.box.lengthIn,widthIn:fallback.box.widthIn,heightIn:fallback.box.heightIn}}});if(result.error||!result.data?.rates?.length)return fallback;const rate=result.data.rates[0];return{...fallback,amount:Number(rate.amount)||fallback.amount,method:rate.serviceName||'UPS shipping',rates:result.data.rates};}catch(error){return fallback;}};
