function categoryFor(row){const titleTags=`${row.TITLE} ${row.TAGS}`.toLowerCase();if(beadableProductPatterns.some((pattern)=>pattern.test(titleTags)))return'beadable-products';if(titleTags.includes('clearance'))return'clearance-section';if(/completed.*(pen|keychain)|finished.*(pen|keychain)/.test(titleTags))return'completed-pens-keychains';if(/cup accessories, cup charm,/.test(titleTags))return'cup-charms';if((titleTags.includes('charm')||titleTags.includes('dangle'))&&!titleTags.includes('cup charm'))return'charms-dangles';if(titleTags.includes('focal'))return'focal-beads';if(titleTags.includes('flatback'))return'acrylic-flatbacks';if(titleTags.includes('rhinestone'))return'rhinestone-beads';if((titleTags.includes('spacer')||titleTags.includes('accessor'))&&!titleTags.includes('cup charm')&&!titleTags.includes('cup accessor'))return'spacers-accessories';if(titleTags.includes('mix')||titleTags.includes('bundle')||titleTags.includes('kit'))return'mixes-bundles-kits';if(/beadable.*pen.*blank|beaded.*pen.*blank|pen.*blank/.test(titleTags))return'beadable-pen-blanks';if(/10\s*(\/|or)\s*12\s*mm|10mm|12mm/.test(titleTags)&&titleTags.includes('acrylic'))return'10-12mm-acrylic-beads';if(/16\s*mm/.test(titleTags)&&titleTags.includes('acrylic'))return'16mm-acrylic-beads';if(/20\s*mm/.test(titleTags)&&titleTags.includes('acrylic'))return'20mm-acrylic-beads';if(titleTags.includes('silicone'))return(/print|paw|letter|face|pattern|design|swirl/.test(titleTags)?'silicone-printed-style':'silicone-solid-color');return'uncategorized';}
