const productCardPricing=(item)=>{const variants=(item.options||[]).flatMap((option)=>option.values||[]).filter((value)=>typeof value==='object'&&String(value.sku||value.inventorySku||'').trim()&&Number.isFinite(Number(value.price)));if(!variants.length){const price=Number(item.displayPrice??item.price);return {multiple:false,label:Number.isFinite(price)?`$${price.toFixed(2)}`:''};}const lowest=variants.reduce((current,value)=>Number(value.price)<Number(current.price)?value:current,variants[0]);const price=Number(lowest.price);const unit=String(lowest.unitType||item.unitType||'Each').trim()||'Each';return {multiple:variants.length>1,label:`${variants.length>1?'Prices starting at ':''}$${price.toFixed(2)} / ${unit}`};};
renderProductCards=(list,target,options={})=>{if(!target)return;const wished=wishlistItems();target.replaceChildren(...list.map((item)=>{const pricing=productCardPricing(item);const hasMultipleSkus=pricing.multiple;const inBag=!hasMultipleSkus&&isInBag(item.id);const badges=storefrontBrowseBadges(item);const topBadges=badges.filter((badge)=>['Single Bead','Multi-Pack','Single Bead & Multi-Pack','Fits on Beadable Pen'].includes(badge));const inventoryBadges=badges.filter((badge)=>['On Sale','Clearance','Low Stock','Out of Stock'].includes(badge));const badgeSpan=(badge)=>`<span class="product-badge product-badge-${badge.toLowerCase().replace(/[^a-z0-9]+/g,'-')}">${escapeProductText(badge)}</span>`;const badgeMarkup=badges.length?`<div class="product-badges product-card-badges">${topBadges.length?`<div class="product-badge-row product-badge-row-top">${topBadges.map(badgeSpan).join('')}</div>`:''}${inventoryBadges.length?`<div class="product-badge-row product-badge-row-bottom">${inventoryBadges.map(badgeSpan).join('')}</div>`:''}</div>`:'';const card=document.createElement('article');card.className='product-card';card.dataset.seoTitle=item.seoTitle;card.dataset.searchText=item.searchText;card.innerHTML=`<a class="product-card-link" href="product.html?id=${encodeURIComponent(item.id)}"><div class="product-card-image-wrap"><img loading="lazy" class="product-card-image" src="${escapeProductText(item.image)}" alt="${escapeProductText(item.name)}">${badgeMarkup}</div><h3>${escapeProductText(item.name)}</h3></a><strong>${pricing.label}</strong><div class="product-actions"><button type="button" class="cart-toggle${inBag?' in-cart':''}" data-cart-toggle="${item.id}" data-choose-options="${hasMultipleSkus?'true':'false'}">${hasMultipleSkus?'Choose Options':inBag?'Remove from Cart':'Add to Cart'}</button><button type="button" class="wishlist-button${wished.includes(item.id)?' active':''}" data-wishlist="${item.id}" aria-label="${wished.includes(item.id)?'Remove from':'Add to'} wishlist">♡</button>${options.cart?`<button type="button" class="remove-cart" data-remove="${item.id}">Remove</button>`:''}</div>`;return card;}));target.querySelectorAll('[data-cart-toggle]').forEach((button)=>button.addEventListener('click',()=>{if(button.dataset.chooseOptions==='true'){window.location.href='product.html?id='+encodeURIComponent(button.dataset.cartToggle);return;}if(isInBag(button.dataset.cartToggle)){removeFromBag(button.dataset.cartToggle);button.textContent='Add to Cart';button.classList.remove('in-cart');}else{addToBag(button.dataset.cartToggle);button.textContent='Remove from Cart';button.classList.add('in-cart');}}));target.querySelectorAll('[data-remove]').forEach((button)=>button.addEventListener('click',()=>{removeFromBag(button.dataset.remove);button.closest('.product-card').remove();}));target.querySelectorAll('[data-wishlist]').forEach((button)=>button.addEventListener('click',()=>{button.classList.toggle('active',toggleWishlist(button.dataset.wishlist));}));};
